// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(c));
        vm.assume(target != address(this));
        vm.deal(address(c), value);
        bool ok;
        try c.sendMoney(target, value) { ok = true; } catch { ok = false; }
        assertTrue(ok || address(c).balance == 0);
    }
}
